def zcols(D):
    out=[]
    for r0,r1 in [(0,3),(3,6),(6,7)]:
        for c0,c1 in [(0,3),(3,6),(6,7)]:
            col=D[r0:r1,c0:c1].flatten()
            cnt=collections.Counter(col)
            nz=int((col!=0).sum())
            uniqc=sum(1 for v,n in cnt.items() if n==1 and v!=0)
            nzv=[v for v in cnt if v]
            out.append({'nz':nz,'ndom':cnt.most_common(1)[0][1],'ncc':len(cnt),
                        'max':int(col.max()),'min':int(min(nzv)) if nzv else 99,
                        'mod3sum':int((col%3).sum()),'odd':int((col%2).sum()),
                        'even':int((col%2==0).sum()),'uniqc':uniqc})
    return out
